class Solution {
public:
    ListNode* sortLinkedList(ListNode* head) {
        if (!head) return head;
        ListNode* prev = head;
        ListNode* current = head->next;
        while (current) {
            if (current->val < 0) {
                prev->next = current->next;
                current->next = head;
                head = current;
                current = prev->next;
            } else {
                prev = current;
                current = current->next;
            }
        }
        return head;
    }
};
